'use strict';
const frame=document.getElementById('subject'),out=document.getElementById('output');let rows=[],errors=[],running=false;
const sleep=ms=>new Promise(r=>setTimeout(r,ms)),doc=()=>frame.contentDocument,win=()=>frame.contentWindow,snap=()=>win().orbitSnapshot();
function write(name,pass,detail=''){rows.push({name,pass,detail});out.textContent=rows.map(r=>`${r.pass?'PASS':'FAIL'} · ${r.name} ${r.detail}`).join('\n');}
const click=id=>doc().getElementById(id).click(),cell=(x,y)=>doc().querySelector(`#grid [data-x="${x}"][data-y="${y}"]`),tool=name=>doc().querySelector(`[data-tool="${name}"]`).click();
function attachErrors(){win().addEventListener('error',e=>errors.push(e.message));win().addEventListener('unhandledrejection',e=>errors.push(String(e.reason)));}
async function reload(){await new Promise(resolve=>{frame.onload=resolve;frame.src='./?qa=1&seed=100&reload='+Date.now();});attachErrors();}
async function waitEnd(){let t=Date.now();while(snap().state==='flying'&&Date.now()-t<35000)await sleep(100);return snap();}
function layout(w,h){frame.style.width=w+'px';frame.style.height=h+'px';const d=doc(),clipped=[...d.querySelectorAll('button,input,select')].filter(e=>e.getClientRects().length).filter(e=>{const r=e.getBoundingClientRect();return r.left<0||r.right>d.documentElement.clientWidth+.5;});return {width:w,height:h,overflow:d.documentElement.scrollWidth>d.documentElement.clientWidth,clipped:clipped.length};}
document.getElementById('run').onclick=async()=>{if(running)return;running=true;document.getElementById('run').disabled=true;rows=[];errors=[];try{
localStorage.removeItem('orbit-workshop-qa-v1');await reload();write('빈 저장값 기본 설계',snap().modules===5&&snap().launches===0);localStorage.setItem('orbit-workshop-qa-v1','{broken');await reload();write('손상 저장 복구',snap().modules===5&&snap().launches===0);
let seed=snap().seed;click('newRoute');write('새 항로에서 행성 재생성',snap().seed!==seed&&snap().t===0);seed=snap().seed;tool('body');cell(6,3).click();write('부품 편집 중 행성 유지',snap().seed===seed);click('clear');tool('cockpit');cell(4,3).click();tool('engine');[3,2,1].forEach(x=>cell(x,3).click());write('3개 일렬 엔진 → 한 묶음',snap().groups.length===1&&snap().groups[0].n===3,doc().getElementById('engines').innerText.replace(/\n/g,' '));let before=snap().groups[0].dir;cell(2,3).click();write('엔진 클릭 시 묶음 전체 방향 전환',snap().groups.length===1&&snap().groups[0].dir!==before);cell(2,3).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2}));write('오른쪽 클릭 1칸 삭제 · 엔진 묶음 분리',snap().modules===3&&snap().groups.length===2);cell(4,3).dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,button:2}));write('조종석 없으면 발사 차단',doc().getElementById('launch').disabled&&snap().state==='design');
click('example');tool('body');let n=snap().modules,t=performance.now();let cells=[...doc().querySelectorAll('#grid .cell')].filter(b=>!b.textContent).slice(0,10).map(b=>[b.dataset.x,b.dataset.y]);cells.forEach(([x,y])=>cell(x,y).dispatchEvent(new MouseEvent('click',{bubbles:true})));let ms=performance.now()-t;write('1초 내 클릭 10건 → 모듈 10개',snap().modules===n+10&&ms<1000,ms.toFixed(1)+'ms');click('example');
for(const [w,h]of [[1366,768],[1920,1080]]){const r=layout(w,h);write('PC 경계 '+w+'×'+h,!r.overflow&&r.clipped===0,JSON.stringify(r));}layout(1366,768);
await reload();click('example');click('launch');await sleep(1700);let a=snap();layout(1920,1080);await sleep(1500);let b=snap();write('크기 변경 후 비행 유지',b.state==='flying'&&b.t>a.t);layout(1366,768);win().dispatchEvent(new Event('blur'));a=snap();await sleep(600);b=snap();write('포커스 이탈 정지',b.paused&&b.t===a.t&&b.x===a.x&&b.angle===a.angle);win().dispatchEvent(new Event('focus'));const resumedAt=Date.now();while(snap().t<=a.t&&Date.now()-resumedAt<5000)await sleep(100);write('포커스 복귀 재개',!snap().paused&&snap().t>a.t);
let end=await waitEnd();write('균형 설계 성공 / 30초 이내',end.state==='success'&&end.t<=30,JSON.stringify(end));write('성공 효과',end.particles>0);doc().getElementById('reduce').checked=true;doc().getElementById('reduce').dispatchEvent(new Event('change'));write('효과 즉시 끄기',snap().particles===0);let count=end.launches;seed=end.seed;click('retry');write('성공 재시작 · 회전 및 현재 판 초기화 · 새 행성',snap().state==='design'&&snap().angle===0&&snap().omega===0&&snap().t===0&&snap().seed!==seed);await reload();write('재접속 보존',snap().launches===count&&snap().wins>0);
click('clear');tool('cockpit');cell(4,2).click();tool('body');cell(4,3).click();tool('engine');cell(4,4).click();cell(4,4).click();click('launch');await sleep(2000);write('하단 측면 엔진 → 실제 회전',Math.abs(snap().angle)>.05&&Math.abs(snap().omega)>.05,JSON.stringify(snap()));end=await waitEnd();write('실패 상태 도달',end.state==='failure',end.state);click('retry');write('실패 재시작 초기화',snap().state==='design'&&snap().omega===0&&snap().t===0);click('example');
if(document.getElementById('longRun').checked){write('10분 실시간 검사 시작',true,new Date().toISOString());let start=Date.now(),rounds=0,next=60000;while(Date.now()-start<600000){if(snap().state!=='flying'){if(snap().state!=='design')click('retry');click('launch');rounds++;}await sleep(250);if(Date.now()-start>=next){write('연속 진행',true,`${Math.floor((Date.now()-start)/1000)}초 / ${rounds}판`);next+=60000;}}await waitEnd();click('retry');tool('body');let n=snap().modules;cell(6,3).click();write('10분 뒤 조작 가능',snap().modules===n+1,`${Date.now()-start}ms / ${rounds}판`);click('example');}else write('검사 범위',true,'변경 기능과 핵심 흐름 검사. 이번 실행에는 10분 연속 검사를 포함하지 않음.');
write('게임 오류 0건',errors.length===0,JSON.stringify(errors));write('검사 종료',true,new Date().toISOString());
}catch(e){write('검사 예외',false,String(e.stack||e));}finally{running=false;document.getElementById('run').disabled=false;}};
